class TicTacToe:
    EMPTY_CELL = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'
    BOARD_SIZE = 3

    def __init__(self, N=3):
        self._board = [[self.EMPTY_CELL for _ in range(N)] for _ in range(self.BOARD_SIZE)]
        self._current_player = self.PLAYER_X

    @property
    def current_player(self):
        return self._current_player

    def make_move(self, row, col):
        if self._is_cell_empty(row, col):
            self._board[row][col] = self._current_player
            self._current_player = self._get_opponent_player(self._current_player)
            return True
        else:
            return False

    def _is_cell_empty(self, row, col):
        return self._board[row][col] == self.EMPTY_CELL

    def _get_opponent_player(self, player):
        return self.PLAYER_O if player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        return (self._check_rows_for_winner() 
                or self._check_columns_for_winner() 
                or self._check_diagonals_for_winner())

    def _check_rows_for_winner(self):
        for row in self._board:
            if row[0] == row[1] == row[2] != self.EMPTY_CELL:
                return row[0]
        return None

    def _check_columns_for_winner(self):
        for col in range(self.BOARD_SIZE):
            if self._board[0][col] == self._board[1][col] == self._board[2][col] != self.EMPTY_CELL:
                return self._board[0][col]
        return None

    def _check_diagonals_for_winner(self):
        if self._board[0][0] == self._board[1][1] == self._board[2][2] != self.EMPTY_CELL:
            return self._board[0][0]
        if self._board[0][2] == self._board[1][1] == self._board[2][0] != self.EMPTY_CELL:
            return self._board[0][2]
        return None

    def is_board_full(self):
        return not any(self.EMPTY_CELL in row for row in self._board)
